import "server-only";
import content from "@/content/docs-site.json";

/**
 * The Help Center's pre-rendered pages (generated by scripts/build-docs-site.mts from docs/ — only the
 * pages docs/site.json publishes). Server-only: the HTML stays out of client bundles.
 */
export interface DocHeading { id: string; text: string; depth: 2 | 3 }
export interface DocPage { slug: string; title: string; description: string; section: string; source: string; reviewed: string; headings: DocHeading[]; html: string }
export interface DocSection { id: string; title: string; audience: string; pages: string[] }

const site = content as unknown as { version: string; latestRelease: string | null; reviewed: string; sections: DocSection[]; pages: Record<string, DocPage> };

export const REPO_URL = "https://github.com/xndrncp08/Diskarte";
export const docsVersion = { app: site.version, latestRelease: site.latestRelease, reviewed: site.reviewed };
export const docSections = site.sections;
const order = site.sections.flatMap((s) => s.pages);

export function getDoc(slug: string): DocPage | null {
  return Object.hasOwn(site.pages, slug) ? site.pages[slug] : null;
}

export function sectionOf(page: DocPage) {
  return site.sections.find((s) => s.id === page.section)!;
}

/** Sidebar order: the previous and next page across every section. */
export function neighbours(slug: string) {
  const i = order.indexOf(slug);
  const at = (j: number) => (j >= 0 && j < order.length ? getDoc(order[j]) : null);
  return { previous: at(i - 1), next: at(i + 1) };
}

export function allDocSlugs() {
  return order;
}

/** "6 November 2026" from an ISO date, independent of the server's time zone. */
export function formatDocDate(iso: string) {
  return new Intl.DateTimeFormat("en-PH", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${iso}T00:00:00Z`));
}
